--   重跑：python _temp/fc_bis.py（--force 重抓 30级 网页；20级 卷只读本地缓存）
--
-- 结构：ns.BIS = { updated, default = 30,
--     levels = { [20] = { updated, classes = {...} }, [30] = { ... } },
--     classes = levels[default].classes }（classes 是运行期别名，界面层沿用旧读取路径）
--   · classes = { { slug, specs = { { id, slots, rows, enchs }, ... } }, ... }
--   · spec.id = "pve" | "pvp" | "tank"（该专精未收录时整条缺省）
--   · slots[slotKey] = { 联盟侧, 部落侧 }，侧 = { itemID, 品质(1-5), 附魔摘要? }，
--     nil = 该侧空（双手武器占副手）；slotKey = head/neck/…/finger/trinket/
--     two-hand / main-hand / off-hand / ranged
--   · rows[slotKey] = { 备选排名, ... }；rank 行 = { item=itemID, q=品质,
--     side="a"|"h"|nil 阵营限定, src=来源, unc=未经确认, mats={{材料ID,数量},...},
--     recipe=图样物品ID }
--   · src 结构化：{ t="quest", q=questID } / { t="boss", dung=副本名, boss=首领,
--     ref=副本id(挂 ns.DungeonData), rate=掉率说明 } / { t="craft", prof=专业slug,
--     lvl=技能等级 } / { t="rare", note=描述 } / { t="books", note=任务名 } /
--     { t="other", note=说明 }
--   · enchs = { { slot=部位中文名(原样), item=公式/卷轴物品ID(训练师附魔无此字段,
--     选中令牌退化为 eff 文本), lvl=附魔技能, eff=加成文本(如「力量 +5」),
--     name=附魔名(仅训练师附魔存文本兜底；公式行走客户端物品名),
--     note=来源说明, mats={{材料ID,数量},...} }, ... }（每专精独立；部位中文键
--     由界面层映射回 slotKey）
--   · ★ 名字 / 图标 / 品质色一律运行期由客户端给（GetItemInfo），本文件只存 ID；
--     附魔摘要与客户端拿不到的来源说明以文本兜底。
-- =============================================================================

